//! Byte-identity vectors for every wire encoding of the key and signature types, across all
//! 17 algorithms.
//!
//! The expected values were generated by pqc-sig **0.4.2**, before the signature backends
//! became optional features in 0.5.0, using `print_encoding_vectors` below on the 0.4.2
//! tree. This file runs in every feature combination, including
//! `--no-default-features --features std` where no signature implementation is compiled,
//! so it proves the encoding-only build produces exactly the bytes the full crate always
//! has.
//!
//! Each entry is the SHA-256 of the encoded string rather than the string itself, because
//! SLH-DSA signatures run to ~66 KB of base64url. The multibase strings are also committed
//! in full in `multibase_tests.rs`.
//!
//! **Never regenerate these to make a test pass.** A changed value is a changed wire
//! format, which is a breaking change under `STABILITY.md`.

use pqc_sig::types::{SigAlgorithm, SigPublicKey, Signature, SignedMessage};
use sha2::{Digest, Sha256};

const ALL: [SigAlgorithm; 17] = [
    SigAlgorithm::MlDsa44,
    SigAlgorithm::MlDsa65,
    SigAlgorithm::MlDsa87,
    SigAlgorithm::SlhDsaSha2_128s,
    SigAlgorithm::SlhDsaSha2_128f,
    SigAlgorithm::SlhDsaSha2_192s,
    SigAlgorithm::SlhDsaSha2_192f,
    SigAlgorithm::SlhDsaSha2_256s,
    SigAlgorithm::SlhDsaSha2_256f,
    SigAlgorithm::SlhDsaShake128s,
    SigAlgorithm::SlhDsaShake128f,
    SigAlgorithm::SlhDsaShake192s,
    SigAlgorithm::SlhDsaShake192f,
    SigAlgorithm::SlhDsaShake256s,
    SigAlgorithm::SlhDsaShake256f,
    SigAlgorithm::FnDsa512,
    SigAlgorithm::FnDsa1024,
];

/// Deterministic, non-random bytes: byte `i` has value `(i * 7 + seed) % 256`.
fn bytes(len: usize, seed: u8) -> Vec<u8> {
    (0..len).map(|i| ((i * 7 + seed as usize) % 256) as u8).collect()
}

fn public_key(algo: SigAlgorithm) -> SigPublicKey {
    SigPublicKey::new(algo, bytes(algo.public_key_size(), 1))
}

fn signature(algo: SigAlgorithm) -> Signature {
    Signature::new(algo, bytes(algo.signature_size(), 2))
}

const MESSAGE: &[u8] = b"pqc-sig encoding vector";

fn sha256_hex(s: &str) -> String {
    Sha256::digest(s.as_bytes()).iter().map(|b| format!("{b:02x}")).collect()
}

/// The five encodings of one algorithm, in a fixed order.
fn encodings(algo: SigAlgorithm) -> [String; 5] {
    let pk = public_key(algo);
    let sig = signature(algo);
    [
        pk.to_multibase().expect("multibase"),
        pk.to_json().expect("public key json"),
        sig.to_base64url(),
        sig.to_json().expect("signature json"),
        SignedMessage::new(MESSAGE.to_vec(), sig.clone(), pk.clone())
            .to_json()
            .expect("signed message json"),
    ]
}

const NAMES: [&str; 5] = [
    "public key multibase",
    "public key json",
    "signature base64url",
    "signature json",
    "signed message json",
];

