#[test]
fn every_algorithm_has_a_vector() {
    assert_eq!(VECTORS.len(), ALL.len(), "one vector per algorithm");
    for (algo, (vector_algo, _)) in ALL.iter().zip(VECTORS) {
        assert_eq!(algo, vector_algo);
    }
}

#[test]
fn encodings_match_the_0_4_2_output() {
    for (algo, expected) in VECTORS {
        for ((name, encoded), want) in NAMES.iter().zip(encodings(*algo)).zip(expected) {
            assert_eq!(&sha256_hex(&encoded), want, "{algo:?} {name}");
        }
    }
}

/// The check can fail: changing one byte of the input changes every digest.
#[test]
fn a_one_byte_change_is_detected() {
    let algo = SigAlgorithm::MlDsa65;
    let mut pk = public_key(algo);
    pk.bytes[0] ^= 1;
    assert_ne!(sha256_hex(&pk.to_multibase().unwrap()), VECTORS[1].1[0]);
    let mut sig = signature(algo);
    sig.bytes[0] ^= 1;
    assert_ne!(sha256_hex(&sig.to_base64url()), VECTORS[1].1[2]);
}

#[test]
fn encodings_decode_to_the_original_values() {
    for algo in ALL {
        let pk = public_key(algo);
        let sig = signature(algo);
        let [multibase, pk_json, sig_b64, sig_json, msg_json] = encodings(algo);

        assert_eq!(SigPublicKey::from_multibase(algo, &multibase).unwrap(), pk, "{algo:?}");
        assert_eq!(SigPublicKey::from_json(&pk_json).unwrap(), pk, "{algo:?}");
        assert_eq!(Signature::from_base64url(algo, &sig_b64).unwrap(), sig, "{algo:?}");
        assert_eq!(Signature::from_json(&sig_json).unwrap(), sig, "{algo:?}");

        let msg = SignedMessage::from_json(&msg_json).unwrap();
        assert_eq!(msg.message, MESSAGE, "{algo:?}");
        assert_eq!(msg.signature, sig, "{algo:?}");
        assert_eq!(msg.public_key, pk, "{algo:?}");
    }
}

/// Prints the `VECTORS` table. Run on the tree whose output is the reference:
/// `cargo test --test encoding_vectors -- --ignored --nocapture print_encoding_vectors`
#[test]
#[ignore = "generator, not a check"]
fn print_encoding_vectors() {
    for algo in ALL {
        let digests: Vec<String> =
            encodings(algo).iter().map(|e| format!("\"{}\"", sha256_hex(e))).collect();
        println!("    (SigAlgorithm::{algo:?}, [\n        {},\n    ]),", digests.join(",\n        "));
    }
}
